import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Simple browser-based Word Guess Game using only the JDK (no Maven/frameworks). */
public class Main {
  static final int PORT=8080, MAX_GUESSES=5, MAX_DAILY=3;
  static final Path DATA=Paths.get("wordgame-data.ser");
  static final List<String> WORDS=Arrays.asList("APPLE","BRAVE","CHAIR","DANCE","EAGLE","FLAME","GRAPE","HOUSE","IVORY","JOKER","KNIFE","LEMON","MANGO","NURSE","OCEAN","PLANT","QUEEN","RIVER","STONE","TIGER");
  static final Map<String,String> sessions=new ConcurrentHashMap<>();
  static Store store;
  static class User implements Serializable {String username, hash, role; User(String u,String h,String r){username=u;hash=h;role=r;}}
  static class Guess implements Serializable {String text; List<String> pattern; Guess(String t,List<String> p){text=t;pattern=p;}}
  static class Round implements Serializable {String username, answer, date, status="in_progress"; List<Guess> guesses=new ArrayList<>(); Round(String u,String a){username=u;answer=a;date=LocalDate.now().toString();}}
  static class Store implements Serializable {Map<String,User> users=new TreeMap<>(String.CASE_INSENSITIVE_ORDER); List<Round> rounds=new ArrayList<>();}
  public static void main(String[] args)throws Exception {
    load();
    HttpServer server=HttpServer.create(new InetSocketAddress(PORT),0); server.createContext("/",Main::handle); server.setExecutor(Executors.newCachedThreadPool());
    System.out.println("Word Guess Game running at http://localhost:"+PORT); server.start();
  }
  static synchronized void load(){try(ObjectInputStream in=new ObjectInputStream(Files.newInputStream(DATA))){store=(Store)in.readObject();}catch(Exception e){store=new Store();}}
  static synchronized void save(){try(ObjectOutputStream out=new ObjectOutputStream(Files.newOutputStream(DATA))){out.writeObject(store);}catch(IOException e){e.printStackTrace();}}
  static String hash(String p){try{byte[] salt="WordGuessJavaSalt".getBytes(StandardCharsets.UTF_8); PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),salt,65000,256); return Base64.getEncoder().encodeToString(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded());}catch(Exception e){throw new RuntimeException(e);}}
  static void handle(HttpExchange x)throws IOException {try{
    String path=x.getRequestURI().getPath(), method=x.getRequestMethod(); Map<String,String> q=parse(x.getRequestURI().getRawQuery()); if(method.equals("POST")) q.putAll(parse(new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8)));
    String user=current(x), flash=""; User u=user==null?null:store.users.get(user);
    if(path.equals("/style.css")){byte[] b=Files.readAllBytes(Paths.get("static/style.css")); x.getResponseHeaders().set("Content-Type","text/css; charset=utf-8");send(x,200,b);return;}
    if(path.equals("/favicon.ico")){send(x,204,new byte[0]);return;}
    if(path.equals("/logout")){String sid=cookie(x,"WGSESSION");sessions.remove(sid);redirect(x,u!=null&&u.role.equals("admin")?"/admin/login":"/login");return;}
    if(path.equals("/")&&u!=null){redirect(x,u.role.equals("admin")?"/admin":"/play");return;}
    if(path.equals("/") ){page(x,"Welcome", "<div class='role-selection'><div class='card role-card'><div class='role-icon'>🎮</div><h1>Player</h1><p class='muted'>Play the Word Guess Game and test your word skills.</p><a href='/login' class='btn role-btn'>Player Login</a><p class='muted'>New player? <a href='/register'>Create an account</a></p></div><div class='card role-card'><div class='role-icon'>⚙️</div><h1>Administrator</h1><p class='muted'>Access the dashboard, reports, and user activity.</p><a href='/admin/login' class='btn role-btn'>Admin Login</a></div></div>");return;}
    if(path.equals("/register")){if(method.equals("POST")){String un=q.getOrDefault("username","").trim(),pw=q.getOrDefault("password","");String err="";if(!un.matches("[A-Za-z]{5,}"))err="Username must be at least 5 letters (letters only).";else if(pw.length()<5||!pw.matches(".*[A-Za-z].*")||!pw.matches(".*[0-9].*")||!pw.matches(".*[$%*].*"))err="Password must be at least 5 characters and include a letter, number, and special character ($ % *).";else if(store.users.containsKey(un))err="That username is already taken.";if(!err.isEmpty()){page(x,"Register",notice(err,"error")+registerForm(un));return;}store.users.put(un,new User(un,hash(pw),"player"));save();page(x,"Register",notice("Registration successful. Please log in.","success")+"<div class='card narrow'><h1>Account created</h1><a class='btn' href='/login'>Player Login</a></div>");return;}page(x,"Register",registerForm(""));return;}
    if(path.equals("/admin/setup")){
      if(hasAdmin()){redirect(x,"/admin/login");return;}
      if(method.equals("POST")){
        String un=q.getOrDefault("username","").trim(),pw=q.getOrDefault("password","");
        String err="";
        if(!un.matches("[A-Za-z]{5,}"))err="Administrator username must be at least 5 letters (letters only).";
        else if(pw.length()<5||!pw.matches(".*[A-Za-z].*")||!pw.matches(".*[0-9].*")||!pw.matches(".*[$%*].*"))err="Password must be at least 5 characters and include a letter, number, and special character ($ % *).";
        else if(store.users.containsKey(un))err="That username is already taken.";
        if(!err.isEmpty()){page(x,"Administrator Setup",notice(err,"error")+adminSetupForm(un));return;}
        store.users.put(un,new User(un,hash(pw),"admin"));save();redirect(x,"/admin/login");return;
      }
      page(x,"Administrator Setup",adminSetupForm(""));return;
    }
    if(path.equals("/login")||path.equals("/admin/login")){boolean admin=path.startsWith("/admin");String target=admin?"admin":"player";if(method.equals("POST")){String un=q.getOrDefault("username","").trim(),pw=q.getOrDefault("password","");User found=store.users.get(un);if(found!=null&&found.role.equals(target)&&constant(hash(pw),found.hash)){String sid=UUID.randomUUID().toString();sessions.put(sid,found.username);x.getResponseHeaders().add("Set-Cookie","WGSESSION="+sid+"; Path=/; HttpOnly; SameSite=Lax");redirect(x,admin?"/admin":"/play");return;}page(x,admin?"Admin Login":"Player Login",notice("Invalid "+target+" username or password.","error")+loginForm(admin));return;}page(x,admin?"Admin Login":"Player Login",loginForm(admin));return;}
    if(path.equals("/play")||path.equals("/play/start")||path.equals("/play/guess")){if(u==null){redirect(x,"/login");return;}if(!u.role.equals("player")){redirect(x,"/admin");return;}if(path.equals("/play/start")){Round active=active(u.username);if(active==null&&today(u.username).size()<MAX_DAILY){Round r=new Round(u.username,WORDS.get(new Random().nextInt(WORDS.size())));store.rounds.add(r);save();}redirect(x,"/play");return;}if(path.equals("/play/guess")){Round r=active(u.username);if(r==null){json(x,400,"{\"error\":\"No active round.\"}");return;}String guess=q.getOrDefault("guess","").trim().toUpperCase();if(!guess.matches("[A-Z]{5}")){json(x,400,"{\"error\":\"Enter a valid 5-letter word (letters only).\"}");return;}if(r.guesses.size()>=MAX_GUESSES){json(x,400,"{\"error\":\"No guesses remaining.\"}");return;}List<String> pat=score(guess,r.answer);r.guesses.add(new Guess(guess,pat));boolean won=guess.equals(r.answer),over=won||r.guesses.size()>=MAX_GUESSES;if(won)r.status="won";else if(over)r.status="lost";save();String msg=won?"Congratulations! You guessed the word!":over?"Better luck next time! The word was "+r.answer+".":"";json(x,200,"{\"guess\":"+js(guess)+",\"pattern\":"+jsonArray(pat)+",\"game_over\":"+over+",\"won\":"+won+",\"message\":"+js(msg)+",\"guess_number\":"+r.guesses.size()+",\"max_guesses\":5}");return;}page(x,"Word Guess Game",game(u.username));return;}
    if(path.equals("/admin")||path.equals("/admin/daily")||path.equals("/admin/user")){if(u==null){redirect(x,"/admin/login");return;}if(!u.role.equals("admin")){redirect(x,"/play");return;}if(path.equals("/admin")){page(x,"Admin", "<div class='card'><h1>Admin Dashboard</h1><p class='muted'>Welcome, "+esc(u.username)+".</p><ul class='admin-links'><li><a href='/admin/daily'>Daily Report</a> — users active and results for a given day</li><li><a href='/admin/user'>User Report</a> — words tried and correct guesses per date</li></ul></div>");return;}if(path.equals("/admin/daily")){String day=q.getOrDefault("date",LocalDate.now().toString());List<Round> rs=new ArrayList<>();Set<String> players=new HashSet<>();int wins=0;for(Round r:store.rounds)if(r.date.equals(day)){rs.add(r);players.add(r.username);if(r.status.equals("won"))wins++;}StringBuilder b=new StringBuilder("<div class='card'><h1>Daily Report</h1><form class='inline-form'><label>Date</label><input type='date' name='date' value='"+esc(day)+"'><button class='btn'>View</button></form><div class='stats-row'><div class='stat-box'><div class='stat-number'>"+players.size()+"</div><div class='stat-label'>Users Played</div></div><div class='stat-box'><div class='stat-number'>"+rs.size()+"</div><div class='stat-label'>Words Attempted</div></div><div class='stat-box'><div class='stat-number'>"+wins+"</div><div class='stat-label'>Correct Guesses</div></div></div><h2>Details for "+esc(day)+"</h2>");if(rs.isEmpty())b.append("<p class='muted'>No games were played on this date.</p>");else{b.append("<table class='report-table'><tr><th>User</th><th>Word</th><th>Status</th><th>Guesses Used</th></tr>");for(Round r:rs)b.append("<tr><td>"+esc(r.username)+"</td><td>"+r.answer+"</td><td>"+status(r.status)+"</td><td>"+r.guesses.size()+"</td></tr>");b.append("</table>");}page(x,"Daily Report",b.toString());return;}if(path.equals("/admin/user")){String name=q.getOrDefault("username","").trim();User selected=store.users.get(name);StringBuilder b=new StringBuilder("<div class='card'><h1>User Report</h1><form method='GET' class='inline-form'><label>Username</label><input type='text' name='username' value='"+esc(name)+"' list='player-list' placeholder='Enter player username'><datalist id='player-list'>");for(User p:store.users.values())if(p.role.equals("player"))b.append("<option value='"+esc(p.username)+"'>");b.append("</datalist><button class='btn'>View</button></form>");if(!name.isEmpty()){if(selected==null||!selected.role.equals("player"))b.append(notice("No player found with username '"+esc(name)+"'.","error"));else{b.append("<h2>Results for "+esc(name)+"</h2><table class='report-table'><tr><th>Date</th><th>Words Tried</th><th>Correct Guesses</th></tr>");Map<String,int[]> stats=new TreeMap<>(Collections.reverseOrder());for(Round r:store.rounds)if(r.username.equalsIgnoreCase(name)){int[] a=stats.computeIfAbsent(r.date,k->new int[2]);a[0]++;if(r.status.equals("won"))a[1]++;}for(String d:stats.keySet())b.append("<tr><td>"+d+"</td><td>"+stats.get(d)[0]+"</td><td>"+stats.get(d)[1]+"</td></tr>");if(stats.isEmpty())b.append("<tr><td colspan='3'>This user hasn't played any games yet.</td></tr>");b.append("</table>");}}b.append("</div>");page(x,"User Report",b.toString());return;}}
    page(x,"Not Found","<div class='card'><h1>Page not found</h1><a href='/'>Home</a></div>");
  }catch(Exception e){e.printStackTrace();try{page(x,"Error","<div class='card'><h1>Something went wrong</h1><p>Please try again.</p></div>");}catch(Exception ignored){}}}
  static String current(HttpExchange x){String id=cookie(x,"WGSESSION");return sessions.get(id);} static String cookie(HttpExchange x,String name){String c=x.getRequestHeaders().getFirst("Cookie");if(c!=null)for(String p:c.split(";")){String[] a=p.trim().split("=",2);if(a.length==2&&a[0].equals(name))return a[1];}return "";}
  static Map<String,String> parse(String raw){Map<String,String> m=new HashMap<>();if(raw!=null)for(String p:raw.split("&")){String[] a=p.split("=",2);try{m.put(URLDecoder.decode(a[0],"UTF-8"),a.length>1?URLDecoder.decode(a[1],"UTF-8"):"");}catch(Exception ignored){}}return m;}
  static void page(HttpExchange x,String title,String body)throws IOException{String user=current(x);User u=user==null?null:store.users.get(user);String nav="<nav class='navbar'><a class='brand' href='/'>Word Guess</a><div class='nav-links'>"+(u==null?"<a href='/login'>Player Login</a><a href='/admin/login'>Admin Login</a><a href='/register'>Register</a>":(u.role.equals("admin")?"<a href='/admin'>Dashboard</a><a href='/admin/daily'>Daily Report</a><a href='/admin/user'>User Report</a>":"<a href='/play'>Play</a>")+"<span class='nav-user'>"+esc(u.username)+" ("+esc(u.role)+")</span><a href='/logout'>Logout</a>")+"</div></nav>";String html="<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+esc(title)+"</title><link rel='stylesheet' href='/style.css'></head><body>"+nav+"<main class='container'>"+body+"</main></body></html>";x.getResponseHeaders().set("Content-Type","text/html; charset=utf-8");send(x,200,html.getBytes(StandardCharsets.UTF_8));}
  static String registerForm(String un){return "<div class='card narrow'><h1>Create an Account</h1><form method='POST'><label>Username</label><input name='username' value='"+esc(un)+"' required autofocus><p class='hint'>At least 5 letters (letters only, no numbers or symbols).</p><label>Password</label><input type='password' name='password' required><p class='hint'>At least 5 characters, with a letter, a number, and one special character ($ % *).</p><button class='btn'>Register</button></form><p class='muted'>Already have an account? <a href='/login'>Log in</a></p></div>";}
  static String loginForm(boolean admin){return "<div class='card narrow login-card'><h1>"+(admin?"Admin Login":"Player Login")+"</h1><p class='muted'>"+(admin?"Sign in to access the administration dashboard.":"Log in to play the Word Guess Game.")+"</p><form method='POST'><label>"+(admin?"Admin Username":"Username")+"</label><input name='username' required autofocus><label>"+(admin?"Admin Password":"Password")+"</label><input type='password' name='password' required><button class='btn'>"+(admin?"Admin Login":"Player Login")+"</button></form>"+(admin?(!hasAdmin()?"<p class='login-switch'>First time here? <a href='/admin/setup'>Set up an administrator account</a></p>":"")+"<p class='login-switch'>Are you a player? <a href='/login'>Player Login</a></p>":"<p class='muted'>Don't have an account? <a href='/register'>Register here</a></p><p class='login-switch'>Are you an administrator? <a href='/admin/login'>Admin Login</a></p>")+"</div>";}
  static String adminSetupForm(String un){return "<div class='card narrow login-card'><h1>Set Up Administrator</h1><p class='muted'>Create the administrator account for this local application. This setup is available only until an administrator account is created.</p><form method='POST'><label>Administrator Username</label><input name='username' value='"+esc(un)+"' required autofocus><p class='hint'>At least 5 letters (letters only).</p><label>Password</label><input type='password' name='password' required><p class='hint'>At least 5 characters, including a letter, number, and one of $ % *.</p><button class='btn'>Create Administrator</button></form></div>";}
  static boolean hasAdmin(){for(User user:store.users.values())if(user.role.equals("admin"))return true;return false;}
  static String game(String username){List<Round> todays=today(username);Round r=active(username);StringBuilder b=new StringBuilder("<div class='game-page'><section class='card game-card'><div class='game-header'><h1>Word Guess Game</h1><p class='muted'>Guess the five-letter word.</p></div><p class='muted'>Words played today: "+todays.size()+" / 3</p>");if(r==null){if(todays.size()<MAX_DAILY)b.append("<div class='start-section'><p>Ready to test your word skills?</p><form method='POST' action='/play/start'><button class='btn'>Start Game</button></form></div>");else b.append("<div class='notice'>You've reached today's limit of 3 words. Come back tomorrow!</div>");}else{b.append("<div id='board' data-max-guesses='5'>");for(Guess g:r.guesses){b.append("<div class='guess-row'>");for(int i=0;i<5;i++)b.append("<div class='tile "+g.pattern.get(i)+"'>"+g.text.charAt(i)+"</div>");b.append("</div>");}b.append("</div><p id='guesses-left' class='guesses-status'>Guesses used: "+r.guesses.size()+" / 5</p><p id='error-msg' class='error-notice' style='display:none;color:#a12626'></p>");if(r.status.equals("in_progress"))b.append("<form id='guess-form'><input id='guess-input' name='guess' maxlength='5' placeholder='ENTER WORD' autocomplete='off' required><button class='btn'>Guess</button></form>");else b.append("<div class='notice'>This round is finished. <a href='/play'>Continue</a></div>");b.append("<div id='modal-overlay' class='modal-overlay' style='display:none'><div class='modal'><p id='modal-message'></p><button id='modal-ok' class='btn'>OK</button></div></div><script>const form=document.getElementById('guess-form');if(form){const input=document.getElementById('guess-input'),board=document.getElementById('board'),err=document.getElementById('error-msg');form.addEventListener('submit',async e=>{e.preventDefault();err.style.display='none';let guess=input.value.trim().toUpperCase();if(!/^[A-Z]{5}$/.test(guess)){err.textContent='Please enter a valid 5-letter word.';err.style.display='block';return;}let resp=await fetch('/play/guess',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'guess='+encodeURIComponent(guess)});let data=await resp.json();if(data.error){err.textContent=data.error;err.style.display='block';return;}let row=document.createElement('div');row.className='guess-row';data.pattern.forEach((c,i)=>{let tile=document.createElement('div');tile.className='tile '+c;tile.textContent=data.guess[i];row.appendChild(tile);});board.appendChild(row);input.value='';document.getElementById('guesses-left').textContent='Guesses used: '+data.guess_number+' / 5';if(data.game_over){form.style.display='none';document.getElementById('modal-message').textContent=data.message;document.getElementById('modal-overlay').style.display='flex';}});document.getElementById('modal-ok').addEventListener('click',()=>window.location.reload());}</script>");}
    b.append("</section><aside class='rules-card'><div class='rules-header'><span class='rules-icon'>📘</span><h2>How to Play</h2></div><p class='rules-intro'>Guess the hidden five-letter word in five attempts.</p><div class='rule-item'><div class='example-tile green'>A</div><div><strong>Correct letter</strong><span>The letter is in the word and in the correct position.</span></div></div><div class='rule-item'><div class='example-tile orange'>A</div><div><strong>Wrong position</strong><span>The letter is in the word but in the wrong position.</span></div></div><div class='rule-item'><div class='example-tile grey'>A</div><div><strong>Not in word</strong><span>The letter does not appear in the word.</span></div></div><div class='remember-section'><h3>Remember</h3><ul><li>Enter a valid 5-letter word.</li><li>You have 5 attempts.</li><li>You can play up to 3 words daily.</li><li>Use the colored tiles as clues.</li></ul></div></aside></div>");return b.toString();}
  static List<Round> today(String un){List<Round> a=new ArrayList<>();for(Round r:store.rounds)if(r.username.equalsIgnoreCase(un)&&r.date.equals(LocalDate.now().toString()))a.add(r);return a;} static Round active(String un){for(Round r:store.rounds)if(r.username.equalsIgnoreCase(un)&&r.date.equals(LocalDate.now().toString())&&r.status.equals("in_progress"))return r;return null;}
  static List<String> score(String guess,String answer){char[] a=answer.toCharArray(),g=guess.toCharArray();String[] p={"grey","grey","grey","grey","grey"};for(int i=0;i<5;i++)if(g[i]==a[i]){p[i]="green";a[i]=0;g[i]=0;}for(int i=0;i<5;i++)if(g[i]!=0)for(int j=0;j<5;j++)if(a[j]==g[i]){p[i]="orange";a[j]=0;break;}return Arrays.asList(p);}
  static String status(String s){return s.equals("won")?"✅ Won":s.equals("lost")?"❌ Lost":"⏳ In Progress";} static String notice(String s,String type){return "<div class='flash flash-"+type+"'>"+s+"</div>";} static String esc(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");} static boolean constant(String a,String b){return MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}
  static String js(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")+"\"";} static String jsonArray(List<String> a){StringJoiner j=new StringJoiner(",","[","]");for(String s:a)j.add(js(s));return j.toString();}
  static void redirect(HttpExchange x,String path)throws IOException{x.getResponseHeaders().set("Location",path);x.sendResponseHeaders(303,-1);x.close();} static void json(HttpExchange x,int status,String body)throws IOException{x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");send(x,status,body.getBytes(StandardCharsets.UTF_8));} static void send(HttpExchange x,int status,byte[] b)throws IOException{x.getResponseHeaders().set("X-Content-Type-Options","nosniff");x.sendResponseHeaders(status,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
}
